def experiment(inputs):
    import random
    params = inputs.get('parameters', {})
    seeds = inputs.get('seeds', [1, 2, 3])
    results = {}
    for seed in seeds:
        random.seed(seed)
        results[seed] = [random.random() > 0.5]
    return {'measurements': {'accuracy': [1.0]}}

